INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(25161, 'Matthew 11:28', 'Matthew', 11, 28, 'ای تاسو ټول چې د خپلو درنو بارونو څخه ستړي شوي یئ، ماته راشئ او زه به ارام درکړم.', 'ای تاسو تول چې د خپلو درنو بارونو چخه ستری شوی یی، ماته راشی او زه به ارام درکرم.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_11_28.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25162, 'Matthew 11:29', 'Matthew', 11, 29, 'زما جغ په خپله غاړه کېږدئ او زما څخه یې زده کړئ، ځکه چې زه په زړه نرم او عاجز یم او ستاسو زړونه به ارام ومومي.', 'زما جغ په خپله غاره کېزدی او زما چخه یې زده کری، جکه چې زه په زره نرم او عاجز یم او ستاسو زرونه به ارام ومومی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_11_29.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25163, 'Matthew 11:30', 'Matthew', 11, 30, 'ځکه چې زما د جغ وړل اسانه او بار مې سپک دی.»', 'جکه چې زما د جغ ورل اسانه او بار مې سپک دی.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_11_30.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25164, 'Luke 7:1', 'Luke', 7, 1, 'کله چې عیسی خلکو ته خپلې ټولې خبرې وکړې، نو کپرناحوم ته لاړ.', 'کله چې عیسی خلکو ته خپلې تولې خبرې وکرې، نو کپرناحوم ته لار.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_7_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25165, 'Luke 7:2', 'Luke', 7, 2, 'هلته یو رومي منصبدار ؤ او یو نوکر یې درلود چې په هغه ډېر ګران ؤ. هغه نوکر ناروغ ؤ او مرګ ته نژدې ؤ.', 'هلته یو رومی منصبدار و او یو نوکر یې درلود چې په هغه دېر ګران و. هغه نوکر ناروغ و او مرګ ته نژدې و.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_7_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25166, 'Luke 7:3', 'Luke', 7, 3, 'کله چې هغه منصبدار د عیسی په هکله واورېدل، نو یو څو یهودي مشران یې ورولېږل، ترڅو د هغه څخه وغواړي چې راشي او نوکر یې روغ کړي.', 'کله چې هغه منصبدار د عیسی په هکله واورېدل، نو یو چو یهودی مشران یې ورولېزل، ترچو د هغه چخه وغواری چې راشی او نوکر یې روغ کری.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_7_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25167, 'Luke 7:4', 'Luke', 7, 4, 'هغوی عیسی ته راغلل او سختې زارۍ یې ورته وکړې او ورته ویې ویل: «دا سړی په رښتیا د دې وړ دی چې مرسته ورسره وکړې،', 'هغوی عیسی ته راغلل او سختې زاری یې ورته وکرې او ورته ویې ویل: «دا سری په رشتیا د دې ور دی چې مرسته ورسره وکرې،', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_7_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25168, 'Luke 7:5', 'Luke', 7, 5, 'ځکه چې هغه زمونږ د خلکو سره مینه لري او مونږ ته یې کنیسه هم جوړه کړې ده.»', 'جکه چې هغه زمونز د خلکو سره مینه لری او مونز ته یې کنیسه هم جوره کرې ده.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_7_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25169, 'Luke 7:6', 'Luke', 7, 6, 'نو عیسی د هغوی سره لاړ. خو کله چې د هغه کور ته نژدې شو، نو هغه منصبدار خپل څو ملګري ورولېږل چې هغه ته ووایي: «ښاغلیه! خپل ځان دې مه په تکلیفوه، زه د دې لایق نه یم چې زما کور ته راشې', 'نو عیسی د هغوی سره لار. خو کله چې د هغه کور ته نژدې شو، نو هغه منصبدار خپل چو ملګری ورولېزل چې هغه ته ووایی: «شاغلیه! خپل جان دې مه په تکلیفوه، زه د دې لایق نه یم چې زما کور ته راشې', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_7_6.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(25170, 'Luke 7:7', 'Luke', 7, 7, 'او دا مې هم غوره ونه ګڼله چې خپله تاسو ته راشم. ته یوازې حکم وکړه، نو زما نوکر به روغ شي.', 'او دا مې هم غوره ونه ګنله چې خپله تاسو ته راشم. ته یوازې حکم وکره، نو زما نوکر به روغ شی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_7_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25171, 'Luke 7:8', 'Luke', 7, 8, 'ځکه چې زه هم د بل د امر لاندې یم او عسکر زما د امر لاندې دي. کله چې کوم یو ته ووایم چې لاړ شه، نو هغه ځي او بل ته ووایم راشه، نو راځي او خپل نوکر ته ووایم چې دا کار وکړه، نو هغه یې کوي.»', 'جکه چې زه هم د بل د امر لاندې یم او عسکر زما د امر لاندې دی. کله چې کوم یو ته ووایم چې لار شه، نو هغه جی او بل ته ووایم راشه، نو راجی او خپل نوکر ته ووایم چې دا کار وکره، نو هغه یې کوی.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_7_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25172, 'Luke 7:9', 'Luke', 7, 9, 'کله چې عیسی دا واورېدل، نو حیران شو او خلکو ته یې چې ورپسې روان وو، مخ راواړاوه او ویې ویل: «زه تاسو ته وایم چې ما په اسراییلو کې هم داسې ایمان نه دی لیدلی.»', 'کله چې عیسی دا واورېدل، نو حیران شو او خلکو ته یې چې ورپسې روان وو، مخ راواراوه او ویې ویل: «زه تاسو ته وایم چې ما په اسراییلو کې هم داسې ایمان نه دی لیدلی.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_7_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25173, 'Luke 7:10', 'Luke', 7, 10, 'کله چې لېږل شوي کسان بېرته کور ته راستانه شول، نو هغه نوکر یې روغ رمټ ولیده. عیسی د یوې کونډې زوی راژوندی کوي', 'کله چې لېزل شوی کسان بېرته کور ته راستانه شول، نو هغه نوکر یې روغ رمت ولیده. عیسی د یوې کوندې زوی راژوندی کوی', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_7_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25174, 'Luke 7:11', 'Luke', 7, 11, 'بله ورځ عیسی د خپلو شاګردانو او د خلکو د یوې لویې ډلې سره نایین نومي ښار ته لاړ.', 'بله ورج عیسی د خپلو شاګردانو او د خلکو د یوې لویې دلې سره نایین نومی شار ته لار.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_7_11.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(25175, 'Luke 7:12', 'Luke', 7, 12, 'کله چې د ښار دروازې ته نژدې شو، نو یوه جنازه یې ولیدله چې راووتله. دا مړی د یوې کونډې ښځې ‎یوازېنی زوی ؤ او د هغې سره د ښار ګڼ شمېر خلک ملګري وو.', 'کله چې د شار دروازې ته نژدې شو، نو یوه جنازه یې ولیدله چې راووتله. دا مری د یوې کوندې شجې ‎یوازېنی زوی و او د هغې سره د شار ګن شمېر خلک ملګری وو.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_7_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25176, 'Luke 7:13', 'Luke', 7, 13, 'کله چې عیسی هغه ښځه ولیدله، نو زړه یې ورباندې وسوځېده او ورته ویې ویل: «نوره مه ژاړه.»', 'کله چې عیسی هغه شجه ولیدله، نو زره یې ورباندې وسوجېده او ورته ویې ویل: «نوره مه ژاره.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_7_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25177, 'Luke 7:14', 'Luke', 7, 14, 'بیا هغه وروړاندې شو او په تابوت باندې یې لاس کېښود او کومو خلکو چې تابوت وړلو، ودرېدل. عیسی وویل: «ای ځوانه! تاته وایم راپاڅېږه.»', 'بیا هغه وروراندې شو او په تابوت باندې یې لاس کېشود او کومو خلکو چې تابوت ورلو، ودرېدل. عیسی وویل: «ای جوانه! تاته وایم راپاچېزه.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_7_14.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(25178, 'Luke 7:15', 'Luke', 7, 15, 'هغه مړی کښېناست او په خبرو یې پیل وکړ او عیسی هغه بېرته خپلې مور ته وسپاره.', 'هغه مری کشېناست او په خبرو یې پیل وکر او عیسی هغه بېرته خپلې مور ته وسپاره.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_7_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25179, 'Luke 7:16', 'Luke', 7, 16, 'هغوی ټول وېرې واخیستل او د خدای ثنا یې وویله او ویې ویل: «په مونږ کې یو لوی پیغمبر پیدا شوی دی. خدای راغلی چې د خپل قوم سره مرسته وکړي.»', 'هغوی تول وېرې واخیستل او د خدای ثنا یې وویله او ویې ویل: «په مونز کې یو لوی پیغمبر پیدا شوی دی. خدای راغلی چې د خپل قوم سره مرسته وکری.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_7_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25180, 'Luke 7:17', 'Luke', 7, 17, 'عیسی چې څه کړي وو د هغو خبر په ټولې یهودیې او شاوخوا سیمو کې خپور شو. د عیسی په هکله د یحیی پوښتنه (متي ۱۱‏:‌۲‌‏-‌۱۹)', 'عیسی چې چه کری وو د هغو خبر په تولې یهودیې او شاوخوا سیمو کې خپور شو. د عیسی په هکله د یحیی پوشتنه (متی ۱۱‏:‌۲‌‏-‌۱۹)', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_7_17.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(25181, 'Luke 7:18', 'Luke', 7, 18, 'د یحیی شاګردانو هغه د دې ټولو کارونو څخه خبر کړ. نو یحیی د هغوی څخه دوه تنه راوغوښتل', 'د یحیی شاګردانو هغه د دې تولو کارونو چخه خبر کر. نو یحیی د هغوی چخه دوه تنه راوغوشتل', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_7_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25182, 'Luke 7:19', 'Luke', 7, 19, 'او هغوی یې عیسی ته ورولېږل چې پوښتنه ورڅخه وکړي: «ایا ته هغه څوک یې چې ویل شوي وو باید راغلی وای، یا د کوم بل چا په تمه واوسو؟»', 'او هغوی یې عیسی ته ورولېزل چې پوشتنه ورچخه وکری: «ایا ته هغه چوک یې چې ویل شوی وو باید راغلی وای، یا د کوم بل چا په تمه واوسو؟»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_7_19.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(25183, 'Luke 7:20', 'Luke', 7, 20, 'کله چې هغوی عیسی ته ورغلل، ورته ویې ویل: «مونږ تعمید ورکوونکي یحیی تاته رالېږلي یو چې پوښتنه وکړو چې ته هغه څوک یې چې باید راغلی وای یا د کوم بل چا په تمه واوسو؟»', 'کله چې هغوی عیسی ته ورغلل، ورته ویې ویل: «مونز تعمید ورکوونکی یحیی تاته رالېزلی یو چې پوشتنه وکرو چې ته هغه چوک یې چې باید راغلی وای یا د کوم بل چا په تمه واوسو؟»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_7_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25184, 'Luke 7:21', 'Luke', 7, 21, 'په هماغه ساعت عیسی ډېر خلک د ډول ډول ناروغیو، طاعون او پېریانو څخه روغ کړل او ډېر ړانده یې بینا کړل.', 'په هماغه ساعت عیسی دېر خلک د دول دول ناروغیو، طاعون او پېریانو چخه روغ کرل او دېر رانده یې بینا کرل.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_7_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25185, 'Luke 7:22', 'Luke', 7, 22, 'هغه د یحیی استازو ته په ځواب کې وویل: «بېرته لاړ شئ او څه مو چې لیدلي او اورېدلي، هغه یحیی ته ووایئ چې څنګه ړانده بینا کیږي، ګوډان کولای شي وګرځي، کوم خلک چې په جذام باندې اخته وو هغه پاک او روغ شوي دي او کاڼه اوري، مړي راژوندي کیږي او غریبانو ته زېری ورکول کیږي.', 'هغه د یحیی استازو ته په جواب کې وویل: «بېرته لار شی او چه مو چې لیدلی او اورېدلی، هغه یحیی ته ووایی چې چنګه رانده بینا کیزی، ګودان کولای شی وګرجی، کوم خلک چې په جذام باندې اخته وو هغه پاک او روغ شوی دی او کانه اوری، مری راژوندی کیزی او غریبانو ته زېری ورکول کیزی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_7_22.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(25186, 'Luke 7:23', 'Luke', 7, 23, 'بختور دی هغه څوک چې په ما شک ونه کړي.»', 'بختور دی هغه چوک چې په ما شک ونه کری.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_7_23.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
